import test from 'node:test';
import assert from 'node:assert/strict';
import {createTrajectory} from './trajectory.js';
import {journeyStages,evidenceTopics,possibilityTracks,prioritySteps} from './trajectory-page.js';
class Node {
 constructor(attrs={}){this.attrs={...attrs};this.dataset={};this.listeners=new Map;this.classes=new Set;this.classList={toggle:(key,on)=>on?this.classes.add(key):this.classes.delete(key)};this.textContent='';this.children=[];this.focuses=0;this.parentElement=null;}
 get id(){return this.attrs.id||'';}set id(value){this.attrs.id=value;}
 getAttribute(key){return Object.hasOwn(this.attrs,key)?String(this.attrs[key]):null;}
 setAttribute(key,value){this.attrs[key]=String(value);}
 removeAttribute(key){delete this.attrs[key];}
 set tabIndex(value){this.setAttribute('tabindex',value);}get tabIndex(){return Number(this.getAttribute('tabindex'));}
 addEventListener(type,fn){const a=this.listeners.get(type)||[];a.push(fn);this.listeners.set(type,a);}
 removeEventListener(type,fn){this.listeners.set(type,(this.listeners.get(type)||[]).filter(x=>x!==fn));}
 dispatch(type,values={}){const event={type,prevented:false,stopped:false,preventDefault(){this.prevented=true;},stopPropagation(){this.stopped=true;},...values};for(const fn of [...this.listeners.get(type)||[]])fn(event);return event;}
 closest(){return this.parentElement;}focus(){this.focuses++;}replaceChildren(...nodes){this.children=nodes;}
}
function fixture(){const root=new Node,win=new Node;const nodes=new Map,groups={};root.ownerDocument={createElement:()=>new Node};
 const definitions=[['stage','[data-journey-stage]','journeyStage',journeyStages,'trajectory-stage-panel'],['evidence','[data-evidence-tab]','evidenceTab',evidenceTopics,'trajectory-evidence-panel'],['possibility','[data-possibility-tab]','possibilityTab',possibilityTracks,'trajectory-possibility-panel']];
 for(const[key,selector,attribute,values,panelID]of definitions){const parent=new Node;const buttons=Object.keys(values).map((id,i)=>{const node=new Node({'aria-pressed':String(i===0)});node.dataset[attribute]=id;node.parentElement=parent;return node;});const panel=new Node({id:panelID});nodes.set(selector,buttons);nodes.set('#'+panelID,panel);groups[key]={parent,buttons,panel};}
 for(const name of ['stage-title','stage-copy','evidence-title','evidence-body','evidence-list','possibility-title','possibility-body','possibility-preparation','possibility-context','possibility-dedication','next-step-list','next-step-label'])nodes.set(`[data-${name}]`,new Node);
 const radios=Object.keys(prioritySteps).map((value,i)=>Object.assign(new Node,{value,checked:i===0}));nodes.set('input[name="journey-priority"]',radios);
 root.querySelector=selector=>nodes.get(selector)||null;root.querySelectorAll=selector=>nodes.get(selector)||[];
 return {root,win,nodes,groups,radios,init(){return createTrajectory(root,{window:win});}};
}
test('three groups enhance with selected tab, named panel and original default content',()=>{const f=fixture(),c=f.init();assert.equal(f.root.dataset.enhanced,'true');for(const g of Object.values(f.groups)){assert.equal(g.parent.getAttribute('role'),'tablist');assert.equal(g.panel.getAttribute('role'),'tabpanel');assert.equal(g.panel.getAttribute('aria-labelledby'),g.buttons[0].id);assert.equal(g.buttons[0].tabIndex,0);assert.ok(g.buttons.slice(1).every(b=>b.tabIndex===-1));assert.equal(g.buttons[0].getAttribute('aria-pressed'),null);}assert.equal(f.nodes.get('[data-stage-title]').textContent,journeyStages.basico.title);c.dispose();});
test('click and Arrow/Home/End navigation select actual content with one tabbable button',()=>{const f=fixture();f.init();const {buttons,panel}=f.groups.evidence;buttons[2].dispatch('click');assert.equal(f.root.dataset.evidence,Object.keys(evidenceTopics)[2]);assert.equal(f.nodes.get('[data-evidence-title]').textContent,Object.values(evidenceTopics)[2].title);const right=buttons[2].dispatch('keydown',{key:'ArrowRight'});assert.ok(right.prevented&&right.stopped);assert.equal(buttons[3].focuses,1);assert.equal(panel.getAttribute('aria-labelledby'),buttons[3].id);buttons[3].dispatch('keydown',{key:'ArrowRight'});assert.equal(buttons[0].getAttribute('aria-selected'),'true');buttons[0].dispatch('keydown',{key:'End'});assert.equal(buttons[3].tabIndex,0);buttons[3].dispatch('keydown',{key:'Home'});buttons[0].dispatch('keydown',{key:'ArrowLeft'});assert.equal(buttons[3].tabIndex,0);assert.equal(buttons.filter(b=>b.tabIndex===0).length,1);});
test('Tab, vertical page navigation and modified keys are not captured',()=>{const f=fixture();f.init();for(const values of [{key:'Tab'},{key:'ArrowDown'},{key:'Escape'},{key:'ArrowRight',ctrlKey:true},{key:'Home',metaKey:true}]){const e=f.groups.stage.buttons[0].dispatch('keydown',values);assert.equal(e.prevented,false);assert.equal(e.stopped,false);}assert.equal(f.root.dataset.stage,'basico');});
test('comparison content and priority checklist are local, truthful data selections',()=>{const f=fixture();f.init();f.groups.possibility.buttons[2].dispatch('click');assert.equal(f.root.dataset.possibility,'internacional');for(const key of ['preparation','context','dedication'])assert.equal(f.nodes.get(`[data-possibility-${key}]`).textContent,possibilityTracks.internacional[key]);f.radios[2].checked=true;f.radios[2].dispatch('change');assert.deepEqual(f.nodes.get('[data-next-step-list]').children.map(n=>n.textContent),prioritySteps.plan.steps);assert.equal(f.root.dataset.priority,'plan');f.radios[1].checked=false;f.radios[1].dispatch('change');assert.equal(f.root.dataset.priority,'plan');});
test('persisted pagehide retains working controls, final pagehide cleans listeners and semantics',()=>{const f=fixture(),c=f.init();f.win.dispatch('pagehide',{persisted:true});f.groups.stage.buttons[1].dispatch('click');assert.equal(f.root.dataset.stage,'clinico');f.win.dispatch('pagehide',{persisted:false});assert.equal(f.root.dataset.enhanced,undefined);assert.equal(f.groups.stage.parent.getAttribute('role'),null);assert.equal(f.groups.stage.panel.getAttribute('aria-labelledby'),null);assert.equal(f.groups.stage.buttons[0].getAttribute('aria-pressed'),'true');f.groups.stage.buttons[2].dispatch('click');assert.equal(f.root.dataset.stage,'clinico');assert.equal(f.win.listeners.get('pagehide').length,0);c.dispose();});
test('missing root and incomplete markup fail open without global handlers or crashes',()=>{createTrajectory(null).dispose();const f=fixture();f.nodes.delete('#trajectory-stage-panel');const c=f.init();assert.equal(f.groups.stage.buttons[0].getAttribute('role'),null);assert.equal(f.root.dataset.enhanced,'true');c.dispose();});

test('layout refresh coalesces initial and changed content and cancels after disposal',()=>{const f=fixture(),frames=new Map;let id=0,layouts=0;f.win.requestAnimationFrame=fn=>{frames.set(++id,fn);return id;};f.win.cancelAnimationFrame=key=>frames.delete(key);const c=createTrajectory(f.root,{window:f.win,onLayout:()=>layouts++});assert.equal(frames.size,1);let run=[...frames.values()][0];frames.clear();run();assert.equal(layouts,1);f.groups.stage.buttons[1].dispatch('click');f.groups.evidence.buttons[3].dispatch('click');assert.equal(frames.size,1);run=[...frames.values()][0];c.dispose();assert.equal(frames.size,0);run();assert.equal(layouts,1);});

test('Space on tabs and native radio keys do not leak into smooth-scroll keyboard handling',()=>{const f=fixture();f.init();const space=f.groups.stage.buttons[0].dispatch('keydown',{key:' '});assert.equal(space.prevented,false);assert.equal(space.stopped,true);for(const key of ['ArrowLeft','ArrowRight','ArrowUp','ArrowDown',' ']){const e=f.radios[0].dispatch('keydown',{key});assert.equal(e.prevented,false);assert.equal(e.stopped,true);}for(const key of ['Tab','PageDown','Escape'])assert.equal(f.radios[0].dispatch('keydown',{key}).stopped,false);assert.equal(f.radios[0].dispatch('keydown',{key:'ArrowLeft',altKey:true}).stopped,false);});
